enum PWR_CR2_PLS {
	PWR_CR2_PLS_Level0 = 0x0, // VPVD0 around 2.0V
	PWR_CR2_PLS_Level1 = 0x2, // VPVD1 around 2.2V
	PWR_CR2_PLS_Level2 = 0x4, // VPVD2 around 2.4V
	PWR_CR2_PLS_Level3 = 0x6, // VPVD3 around 2.5V
	PWR_CR2_PLS_Level4 = 0x8, // VPVD4 around 2.6V
	PWR_CR2_PLS_Level5 = 0xA, // VPVD5 around 2.8V
	PWR_CR2_PLS_Level6 = 0xC, // VPVD6 around 2.9V
	PWR_CR2_PLS_External = 0xE, // External input analog voltage PVD_IN
};
