// USART->RDR Receive data register
enum {
	USART_RDR_RDR = 0x1FF, // Receive data value
};
static inline uint32_t usart_rdr_rdr_get(struct USART_Type* p) { return (p->RDR & USART_RDR_RDR) >> 0; }

// USART->TDR Transmit data register
enum {
	USART_TDR_TDR = 0x1FF, // Transmit data value
};
